#include <vector>

class Solution {
public:
    int sumOfBeautifulSubsequences(std::vector<int>& nums) {
        long long MOD = 1000000007;
        int n = nums.size();
        if (n == 0) return 0;

        long long power = 1;
        for (int i = 0; i < n - 1; ++i) {
            power = (power * 2) % MOD;
        }

        long long ans = 0;
        for (int x : nums) {
            ans = (ans + 1LL * x * power) % MOD;
        }
        return ans;
    }
};

class Solution {
    public int sumOfBeautifulSubsequences(int[] nums) {
        long MOD = 1000000007L;
        int n = nums.length;
        if (n == 0) return 0;

        long power = 1;
        for (int i = 0; i < n - 1; i++) {
            power = (power * 2) % MOD;
        }

        long ans = 0;
        for (int x : nums) {
            ans = (ans + (long) x * power) % MOD;
        }
        return (int) ans;
    }
}

var sumOfBeautifulSubsequences = function(nums) {
    const MOD = 1000000007n;
    const n = nums.length;
    if (n === 0) return 0;

    let power = 1n;
    for (let i = 0; i < n - 1; i++) {
        power = (power * 2n) % MOD;
    }

    let ans = 0n;
    for (const x of nums) {
        ans = (ans + BigInt(x) * power) % MOD;
    }
    return Number(ans);
};
